INSERT INTO `procedure` VALUES (1,'Insulin Blood Level','The insulin concentration in the blood is an important indicator of diabetes.Ontological description: abnormal circulating insulin level [MP:0001560]; increased circulating insulin level [MP:0002079]; decreased circulating insulin level [MP:0002727].',0),(2,'Electrocardiogram (ECG)','To provide a high throughput method to obtain Electrocardiograms in a conscious mouse or an anesthetized mouse.',1),(3,'Gross Pathology and Tissue Collection',NULL,1),(4,'Histopathology',NULL,0),(5,'Welfare Observations','The Welfare Observations procedure is used for the recording of welfare issues as and when they occur.',0),(6,'Gross Morphology Embryo E9.5',NULL,0),(7,'Housing and Husbandry','Housing_and_husbandry',0),(8,'Hematology','Hematological assessment of blood determines blood cell counts (white blood cells red blood cells hemoglobin and platelets) and additional hematological parameters (hematocrit mean cell volume mean corpuscular hemoglobin mean cell hemoglobin concentration) can be derived using these indices. These tests will indicate abnormalities in the production of blood and its components (blood cells and hemoglobin) as well as in the associated blood-forming organs.&nbsp;Ontological description: MP:0002429 - abnormal blood cell morphology/development.',1),(9,'Formalin Test',NULL,0),(10,'Fertility of Homozygous Knock-out Mice','To assess the fertility of homozygous knockout mice.',1),(11,'Combined SHIRPA and Dysmorphology','SHIRPA and dysmorphology were originally always separate assessments.&nbsp; However they have recently been combined as assessments so that they take place at the same time.The purpose of the assessments is to examine mice for obvious physical characteristics behaviors and morphological abnormalities.Descriptions include abnormal locomotion/appearance/behavior/reflex reactions.',1),(12,'Fear Conditioning','Fear Conditioning test assesses aversive learning and memory',0),(13,'X-ray','Construct and analyse digital X-ray images in immobilised mice using a Faxitron X-Ray system or NTB digital X-ray scanner.',1),(14,'Viability E12.5 Secondary Screen',NULL,0),(15,'Gross Morphology Embryo E12.5',NULL,0),(16,'OPT E9.5',NULL,0),(17,'Y-maze','Y-maze assesses learning and memory; it can be used instead/in parallel of Fear Conditioning',0),(18,'Light-Dark Test','Light-Dark test monitors the anxiety-related behaviour of mice',0),(19,'Gross Morphology Embryo E14.5-E15.5',NULL,0),(20,'Acoustic Startle and Pre-pulse Inhibition (PPI)',NULL,1),(21,'Embryo LacZ',NULL,0),(22,'MicroCT E14.5-E15.5',NULL,0),(23,'Gross Morphology Embryo E18.5',NULL,0),(24,'MicroCT E9.5',NULL,0),(25,'Clinical Chemistry',NULL,1),(26,'Adult LacZ',NULL,0),(27,'Viability E14.5-E15.5 Secondary Screen',NULL,0),(28,'Eye Morphology','To detect abnormalities in eye morphology.',1),(29,'Immunophenotyping','Immunophenotyping of immune system cells',1),(30,'Viability Primary Screen','Assess the viability of mutant mice of each sex and zygosity.',1),(31,'Indirect Calorimetry',NULL,0),(32,'Heart Weight','To evaluate cardiac size using heart weight and body weight.',1),(33,'Viability E18.5 Secondary Screen',NULL,0),(34,'MicroCT E18.5',NULL,0),(35,'Experimental design',NULL,0),(36,'Tissue Embedding and Block Banking','Collect and fix a standard list of tissues from the complete necropsy (see IMPC Gross Pathology &amp; Tissue Collection SOP)Trim the fixed tissues into cassettes for processingEmbed the tissues in paraffin in a standard orientation',0),(37,'Open Field','The Open Field test is used to assess anxiety and exploratory behaviors. It is based on the natural tendency of an animal to explore and to protect itself using avoidance which translates to a normal animal spending more time in the periphery of the Open Field arena than in the center (the most anxiogenic area).',1),(38,'Intraperitoneal glucose tolerance test (IPGTT)',NULL,1),(39,'Echo','To assess the functionality of the heart in order to determine the presence of a mutant phenotype.',0),(40,'Gross Morphology Placenta E9.5',NULL,0),(41,'Challenge Whole Body Plethysmography',NULL,0),(42,'Gross Morphology Placenta E12.5',NULL,0),(43,'Organ Weight','Organ weights from different tissues collected for IMPC',0),(44,'MicroCT E14.5-E15.5 Analysis',NULL,0),(45,'Auditory Brain Stem Response','Auditory brainstem response test determines hearing sensitivity and other physiological parameters using evoked potential recordings in anesthetized mice.Ontological description: MP:0004738 - abnormal brainstem auditory evoked potential.',1),(46,'Body Weight',NULL,1),(47,'Body Composition (DEXA lean/fat)','Measure bone mineral content and density as well as body composition in mice using the DEXA (Dual Energy X-ray Absorptiometry) analyser.',1),(48,'Gross Morphology Placenta E14.5-E15.5',NULL,0),(49,'Viability E9.5 Secondary Screen',NULL,0),(50,'Grip Strength',NULL,1),(51,'Gross Morphology Placenta E18.5',NULL,0);
/*!40000 ALTER TABLE `procedure` ENABLE KEYS */;
UNLOCK TABLES;

